UPDATE banks SET questions_json = '[{"id":1,"type":"single","category":"插补与控制原理","difficulty":2,"question":"逐步比较插补法的四拍工作顺序为：（ ）","options":["A. 偏差判别、进进控制、新偏差计算、终点判别","B. 进给控制、偏差判别、新偏差计算、终点判别","C. 终点判别、新偏差计算、偏差判别、进给控制","D. 终点判别、偏差判别、进给控制、新偏差计算"],"answer":"A","explanation":"对：逐点比较法固定按判别、进给、计算、终判四步循环。错：BCD顺序错误。记：‘判、进、算、终’。"},{"id":2,"type":"single","category":"数控机床与系统","difficulty":1,"question":"数控机床的信息输入方式有：（ ）","options":["A. 按键和CRT显示器","B. 磁带.磁盘.网线","C. 手摇脉冲发生器","D. 以上均正确"],"answer":"D","explanation":"对：MDI面板、外部介质网络传输及手摇轮皆可向系统传送控制信息。错：ABC均不全面。记：能传信号的都算。"},{"id":3,"type":"single","category":"检测与伺服系统","difficulty":1,"question":"实际生产中最常用的数控机床是（ ）。","options":["A. 开环","B. 闭环","C. 半闭环","D. A和B"],"answer":"C","explanation":"对：半闭环系统绕开大惯量传动链，调试方便且精度满足主流要求。错：开环不准，闭环昂贵难稳。记：性价比之王选半闭。"},{"id":4,"type":"single","category":"数控加工工艺","difficulty":2,"question":"数控精铣时，一般应选用（ ）","options":["A. 较大的吃刀量、较低的主轴转速、较高的进给速度","B. 较小的吃刀量、较低的主轴转速、较高的进给速度","C. 较小的吃刀量、较高的主轴转速、较高的进给速度","D. 较小的吃刀量、较高的主轴转速、较低的进给速度"],"answer":"D","explanation":"对：精加工需小吃刀量减小变形，高转速、低进给减小微观残留高度。错：ABC易导致外表粗糙。记：精加工小吃快转慢溜达。"},{"id":5,"type":"single","category":"插补与控制原理","difficulty":2,"question":"脉冲增量法插补的精度所产生的误差不会超过（ ）个脉冲当量。","options":["A. 0.5","B. 1","C. 2","D. 3"],"answer":"B","explanation":"对：脉冲增量法每步最多输出一个进给脉冲，最大单向距离误差不超过1。错：ACD不合规律。记：一步一脉冲，最大误差为1。"},{"id":6,"type":"single","category":"数控编程指令","difficulty":1,"question":"程序中指定刀具长度补偿值的代码是（ ）。","options":["A. G","B. D","C. H","D. M"],"answer":"C","explanation":"对：H代码指定长度补偿值（配合G43/G44）。错：G是准备字，D是半径偏置，M是辅助功能。记：H对应Height长度，D对应Diameter半径。"},{"id":7,"type":"single","category":"数控编程指令","difficulty":1,"question":"为减少编程时的计算量，车削编程时常采用（ ）。","options":["A. 半径编程","B. 直径编程","C. 长度编程","D. 以上均使用"],"answer":"B","explanation":"对：图纸多标直径，直径编程可直接抄数值防算错。错：半径编程需反复除以2，易出错。记：车床编程对准图纸用直径。"},{"id":8,"type":"single","category":"数控加工工艺","difficulty":1,"question":"对刀的方法有( )。","options":["A. 手动对刀","B. 自动对刀","C. 机外对刀仪对刀","D. 以上全是"],"answer":"D","explanation":"对：手动试切、触头探测与机外测量均为常用对刀手段。错：ABC均不全面。记：条条大路通罗马，对刀方法全包含。"},{"id":9,"type":"single","category":"数控编程指令","difficulty":1,"question":"G71.G72.G73是加工循环指令，通常用于（ ）的加工状况。","options":["A. 粗车","B. 精车","C. 粗铣","D. 精铣"],"answer":"A","explanation":"对：G71/G72/G73均属于车削复合粗加工循环。错：精车用G70，铣削不用此类代码。记：7字头复合循环，车削粗加工去余量。"},{"id":10,"type":"single","category":"数控机床与系统","difficulty":1,"question":"目前PLC使用最普遍的编程语言是( )","options":["A. 电路图","B. 梯形图","C. 状态图","D. 柱形图"],"answer":"B","explanation":"对：梯形图沿用继电器控制电路形式，直观且符合电气工程师习惯。错：ACD非主流普及语言。记：PLC代名词就是梯形图。"},{"id":11,"type":"single","category":"数控编程指令","difficulty":2,"question":"以下G指令中用于螺纹车削循环的是（ ）。","options":[{"text":"A. G90","img":""},{"text":"B. G91","img":""},{"text":"C. G80","img":""},{"text":"D. G82","img":""}],"answer":"D","explanation":"在使用 G82 循环时，通常需要设置以下关键参数：\\nX / Z：螺纹终点坐标（绝对值或相对值）。\\nI：起始点与终点的半径差（决定牙深）。\\nF：进给速度或每转进给量。\\n✅ 对比其他选项\\nG80：取消循环指令，不执行任何加工。\\nG91：增量定位模式。\\nG90：绝对定位模式。","img":""},{"id":12,"type":"single","category":"数控机床与系统","difficulty":2,"question":"由设计制造和管理的信息计算机化生产过程及物流控制柔性化的整个计算机制造系统简称为( )","options":["A. FMS","B. CIMS","C. DNC","D. FA"],"answer":"B","explanation":"对：CIMS指计算机集成制造系统，实现了CAD/CAM与MIS管理的全面集成。错：A指柔性制造，C指分布式数控。记：全面大集成叫CIMS。"},{"id":13,"type":"single","category":"数控编程指令","difficulty":2,"question":"以下G代码中与G01不同组的是（ ）。","options":["A. G00","B. G02","C. G03","D. G04"],"answer":"D","explanation":"对：G00/G01/G02/G03是01组轨迹插补指令。G04是00组非模态。错：ABC同组可模态替换。记：暂停延时（G04）不属于插补走线组。"},{"id":14,"type":"single","category":"数控编程指令","difficulty":1,"question":"当零件图尺寸为链联接(相对尺寸)标注时适宜用( )编程。","options":["A. 绝对值编程","B. 相对值编程","C. 两者混合","D. 先绝对值后相对值编程"],"answer":"B","explanation":"对：相对标注链式尺寸环环相扣，用相对值编程（增量编程）最省计算量。错：ACD增加额外换算。记：链式标注配相对增量。"},{"id":15,"type":"single","category":"数控编程指令","difficulty":2,"question":"使用G72编程特别适用于（ ）的工件。","options":["A. 径向加工余量较大，轴向加工余量较小","B. 轴向余量较大，径向余量较小","C. 径向和轴向余量均较大","D. 任意形状"],"answer":"A","explanation":"对：G72是端面（横向）粗车循环，进刀平行于X轴，适合饼类盘类零件。错：BCD不属于端面粗车的核心优势。记：饼类端面余量大选G72。"},{"id":16,"type":"single","category":"数控编程指令","difficulty":2,"question":"开机时默认的主轴控制指令为( )","options":["A. G50","B. G96","C. G97","D. G90"],"answer":"C","explanation":"对：安全起见，开机默认恒转速（G97），防止突发超速危险。错：G96是恒线速，需指定G50最高速限制。记：安全第一，默认恒转速（G97）。"},{"id":17,"type":"single","category":"数控编程指令","difficulty":1,"question":"数控机床编程时，在一个程序中（ ）。","options":["A. 只能用绝对尺寸编程","B. 只能用相对尺寸编程","C. 只能用增量尺寸编程","D. 绝对尺寸和增量尺寸可以混合使用"],"answer":"D","explanation":"对：现代系统均支持在同一程序段或程序中混合绝对与增量尺寸。错：ABC说法语意太绝对。记：绝对坐标（XZ）相对坐标（UW）混合用。"},{"id":18,"type":"single","category":"数控编程指令","difficulty":2,"question":"程序段号为G98 G01 W-100 F100则刀具移动时的进速为( )","options":["A. 100mm/r","B. 100mm/min","C. 100m/r","D. 100m/min"],"answer":"B","explanation":"对：G98模态代表每分钟进给，所以F100代表 100mm/min。错：G99才是每转进给。记：98送分（分钟），99看转（每转）。"},{"id":19,"type":"single","category":"数控机床与系统","difficulty":1,"question":"数控机床的CNC系统具有（ ）的特点。","options":["A. 实时性","B. 多任务性","C. 专用性","D. 以上都包括"],"answer":"D","explanation":"对：CNC是专用控制机，需要边插补、边显示、边监控PLC，具备三大工业特性。错：ABC不全面。记：工控系统硬核三特性。"},{"id":20,"type":"single","category":"数控编程指令","difficulty":1,"question":"M09表示( )","options":["A. 冷却液开","B. 冷却液关","C. 夹紧","D. 松开"],"answer":"B","explanation":"对：M08表示切削冷却液开，M09表示冷却液关。错：ACD对应其他辅助开关。记：8开9关。"},{"id":21,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"细分驱动电路可使步进电机的步距角（ ）。","options":["A. 减小","B. 增大","C. 波动","D. 不确定"],"answer":"A","explanation":"对：细分驱动通过阶梯改变绕组电流，使原固定机械步距变小变密。错：BCD背离细分初衷。记：细分就是让脚步变小。"},{"id":22,"type":"single","category":"数控编程指令","difficulty":1,"question":"( )是G71.G74.G73粗加工后精加工指令。","options":["A. G75","B. G76","C. G70","D. G90"],"answer":"C","explanation":"对：G70专门用来调用ns-nf精车轨迹完成最终一刀精加工。错：G75是切槽循环，G76是螺纹。记：71粗车去肉，70精车成型。"},{"id":23,"type":"single","category":"数控编程指令","difficulty":3,"question":"车削M30×1.5（双头）螺纹时，以下代码正确的是（ ）。","options":["A. F1.5","B. F3","C. F30","D. F60"],"answer":"B","explanation":"对：多头螺纹编程F代指导程，$导程 = 头数 \\\\times 螺距 = 2 \\\\times 1.5 = 3\\\\text{mm}$。错：A误将F当成了单头螺距。记：多头车削F是导程。"},{"id":24,"type":"single","category":"数控编程指令","difficulty":2,"question":"切削循环G73适用于加工( )形状。","options":["A. 圆柱","B. 圆锥","C. 铸毛坯","D. 球"],"answer":"C","explanation":"对：G73是封闭仿形循环，按固定轮廓轨迹平移剥离，最适宜加工余量均匀的铸/锻造毛坯。错：ABD用G71效益更高。记：毛坯件仿形找73。"},{"id":25,"type":"single","category":"检测与伺服系统","difficulty":1,"question":"闭环数控机床的检测装置安装在（ ）。","options":["A. 工作台","B. 丝杠","C. 电机轴","D. 以上均可能"],"answer":"A","explanation":"对：全闭环系统的精髓就是直接测量最终运动执行件（工作台）。错：装在丝杠或电机轴属于半闭环。记：全闭环直盯终点工作台。"},{"id":26,"type":"single","category":"数控机床与系统","difficulty":1,"question":"数控车床的回刀架最少能有( )把刀。","options":["A. 5","B. 4","C. 3","D. 2"],"answer":"B","explanation":"对：经济普及型电动回转刀架最基础的形式为4工位刀架（可安放4把刀）。错：ACD不合通用工业配置。记：车床入门刀架起步4把刀。"},{"id":27,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"对于闭环和半闭环数控机床来说，运动精度取决于（ ）。","options":["A. 驱动电机的制造精度","B. 机械传动件的制造精度","C. 检测装置的制造精度","D. 以上均包括"],"answer":"C","explanation":"对：负反馈回路可修正机械和电机自身的传动误差，最终控制质量受限于“眼睛”（检测装置）本身的精度。错：ABD误差可被反馈补偿。记：测量的眼睛决定最终精度。"},{"id":28,"type":"single","category":"数控编程指令","difficulty":1,"question":"T0204表示 ( )","options":["A. 2号刀具2号刀补","B. 2号刀具4号刀补","C. 4号刀具2号刀补","D. 4号刀具4号刀补"],"answer":"B","explanation":"对：数控车床T代码中，前两位02代表2号刀，后两位04代表4号刀补值。错：ACD位次读数弄错。记：前两位管刀号，后两位管刀补。"},{"id":29,"type":"single","category":"数控机床与系统","difficulty":2,"question":"以下描述正确的是（ ）。","options":["A. 因硬件处理速度快，所以数控机床的工作均由硬件完成","B. 因软件处理灵活，所以数控机床的工作均由软件完成","C. 数控机床的工作由硬件和软件共同完成，但软件完成的越来越多","D. 数控机床的工作由硬件和软件共同完成，但硬件完成的越来越多"],"answer":"C","explanation":"对：数控是软硬件协同平台，随着微处理器发展，原本硬电路实现的功能正加速转由软件实现。错：ABD极端武断。记：数控趋势软件化。"},{"id":30,"type":"single","category":"数控编程指令","difficulty":1,"question":"增加坐标系中的U对应绝对坐标系中( )值。","options":["A. X","B. Y","C. Z","D. Q"],"answer":"A","explanation":"对：数控车床右手直角系中，X绝对轴对应的相对增量轴符号指定为U。错：C对应W。记：X配U，Z配W。"},{"id":31,"type":"single","category":"数控编程指令","difficulty":1,"question":"刀具半径补偿的作用是（ ）。","options":["A. 简化编程","B. 弥补刀具的制造误差","C. 粗精加工可共用一个程序","D. 以上都包括"],"answer":"D","explanation":"对：半径补偿可解放人工计算刀心轨迹，支持磨损修正和一程多切。错：ABC单提均不全面。记：半径补偿，一专多能全包。"},{"id":32,"type":"single","category":"数控编程指令","difficulty":1,"question":"数控机床的主轴是( )坐标轴。","options":["A. X轴","B. Y轴","C. Z轴","D. U轴"],"answer":"C","explanation":"对：ISO规定极其严格，平行于切削主轴轴线方向一律指定为Z轴。错：X、Y代表横向或水平轴。记：主轴线就是Z轴。"},{"id":33,"type":"single","category":"数控加工工艺","difficulty":2,"question":"铣削内轮廓时，铣刀的半径与工件轮廓半径之间的大小关系是（ ）。","options":["A. 铣刀半径小于工件轮廓半径","B. 铣刀半径大于工件轮廓半径","C. 铣刀半径等于工件轮廓半径","D. 无限制"],"answer":"A","explanation":"对：若铣刀半径大于内凹圆弧半径，拐角插补时必会切入实体产生过切。错：BCD导致无法加工或撞刀。记：小刀洗大孔，刀大必过切。"},{"id":34,"type":"single","category":"数控机床与系统","difficulty":1,"question":"右手直角坐标系中的拇指表示( )轴。","options":["A. X轴","B. Y轴","C. Z轴","D. W轴"],"answer":"A","explanation":"对：右手笛卡儿定则中，大拇指、食指、中指分别对应指向X、Y、Z轴正向。错：BCD顺序错。记：大拇指是X，食指Y，中指Z。"},{"id":35,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"直线型光栅的用途是（ ）。","options":["A. 只能测量位移","B. 只能测量速度","C. 可以鉴别方向","D. 以上均可"],"answer":"D","explanation":"对：通过光电脉冲数测位移，通过测频算速度，通过A/B正交相位差辨别方向。错：ABC过于片面。记：位移速度判方向，光栅全能。"},{"id":36,"type":"single","category":"数控编程指令","difficulty":2,"question":"建立刀尖圆弧半径补偿和撤消补偿程序段一定不能是( )","options":["A. G00程序段","B. G01程序段","C. 圆弧指令程序段","D. 循环程序段"],"answer":"C","explanation":"对：半径补偿偏置计算需依托一段直线进退作为缓冲区，严禁在G02/G03圆弧段执行。错：AB是标准执行建立段。记：圆弧干活必报警，建立撤销找直线。"},{"id":37,"type":"single","category":"数控加工工艺","difficulty":2,"question":"为减小工件的受力变形，铣削时通常沿工件表面的（ ）进刀。","options":["A. 切向","B. 法向","C. 轴向","D. 任意方向"],"answer":"A","explanation":"对：沿轮廓表面切线方向切入可避免切削力突变对工件产生的冲击变形。错：B法向垂直切入易留刀痕。记：切向进刀最丝滑。"},{"id":38,"type":"single","category":"数控编程指令","difficulty":3,"question":"螺纹加工时应注意在两端设置足够的升速进刀段δ1和降速退刀段δ2其数值由主轴转速和( )来确定。","options":["A. 螺纹导程","B. 螺距","C. 进给率","D. 进给速度"],"answer":"A","explanation":"对：螺纹切削由于进给轴有加减速物理惯性，空程距离直接由转速与导程确定的速度决定。错：单头时导程才等同螺距。记：车螺纹看导程定速度。"},{"id":39,"type":"single","category":"数控编程指令","difficulty":1,"question":"取消刀具半径补偿的G代码是（ ）。","options":["A. G41","B. G42","C. G40","D. H49"],"answer":"C","explanation":"对：G40专用作为撤销取消刀具半径补偿偏置的指令。错：G41左偏，G42右偏，H49撤销长度。记：41左42右40撤销。"},{"id":40,"type":"single","category":"数控编程指令","difficulty":1,"question":"增量指令是用各轴的( )直接编程的方法，称为增量编程法。","options":["A. 移动量","B. 进给量","C. 切削量","D. 坐标值"],"answer":"A","explanation":"对：增量编程（相对编程）的核心特征是输入下步需要移动的净移动距离。错：D是绝对值。记：增量就是移动量。"},{"id":41,"type":"single","category":"数控加工工艺","difficulty":3,"question":"铣削如图所示零件，从简化编程的角度考虑，最佳的路线是（ ）。","options":[{"text":"A. 1","img":""},{"text":"B. 2","img":""},{"text":"C. 3","img":""},{"text":"D. 以上均可","img":""}],"answer":"B","explanation":"对：直母线类三维表面，图(b)沿母线作往复直走刀计算简单且程序最短，保障直纹质量。错：AC路径计算琐碎。记：直纹面顺着母线切（选2）。","img":"https://cdn.jsdu.cn/opdav/20260607/911e2238faa6b60d41ed80fa82cabef6.png"},{"id":42,"type":"single","category":"数控机床与系统","difficulty":1,"question":"CNC系统的核心部件是（ ）。","options":["A. 程序载体","B. 输入装置","C. 数控装置","D. 机床本体"],"answer":"C","explanation":"对：数控装置是承载译码、计算、运动输出的核心中央工控装置。错：ABD为外部输入介质或物理配套机构。记：系统大脑找数控装置。"},{"id":43,"type":"single","category":"数控编程指令","difficulty":1,"question":"工件安装在卡盘上，机床坐标与工件坐标系是不重合的，为便于编程，应在数控系统中建立一个( )坐标系。","options":["A. 工件","B. 机械","C. 机床","D. 程序"],"answer":"A","explanation":"对：建工件坐标系可彻底解决图纸数据无法与固有机械原点对齐的痛点。错：BC是固定的，D不存在。记：对准图纸建工件坐标系。"},{"id":44,"type":"single","category":"数控机床与系统","difficulty":1,"question":"根据伺服系统的控制方式分类，数控机床可分为（ ）。","options":["A. 开环控制数控机床，闭环数控机床和半闭环数控机床","B. 点位控制机床和轮廓控制数控机床","C. 一般数控机床和多功能数控机床","D. 数控特种加工机床和数控金属成形机床"],"answer":"A","explanation":"对：伺服系统的核心分类标准为有无反馈回路，分为开环、半闭环、闭环。错：B按移动轨迹分，CD工艺用途分。记：反馈方式看开环闭环。"},{"id":45,"type":"single","category":"数控编程指令","difficulty":2,"question":"当使用恒线速度切削时，G50 S2000；2000代表( )","options":["A. 主轴最高转速限定","B. 最高切削速度","C. 主轴最低转速","D. 切削速度"],"answer":"A","explanation":"对：恒线速（G96）接近零点时系统算出的速度趋向无穷大，G50专门强制限定其最高安全物理转速。错：BCD意义不符。记：G50 S限制最高速。"},{"id":46,"type":"single","category":"检测与伺服系统","difficulty":1,"question":"现代数控机床的进给工作电机一般都采用（ ）。","options":["A. 异步电机","B. 伺服电机","C. 步进电机","D. 交流电机"],"answer":"B","explanation":"对：现代机床为了保障闭环精度和高频响应，全盘标配“伺服电机”。错：步进电机主要在老旧低端机床上用。记：现代高精必选伺服。"},{"id":47,"type":"single","category":"数控编程指令","difficulty":2,"question":"G32螺纹车削中的F为( )。","options":["A. 螺距","B. 导程","C. 螺纹高度","D. 每分钟进给速度"],"answer":"B","explanation":"对：不论单刀G32还是循环G92，螺纹段内的F参数统一代表几何导程。错：ACD概念弄错。记：螺纹代码内F必是导程。"},{"id":48,"type":"single","category":"数控编程指令","difficulty":3,"question":"采用直径编程的指令是（ ）。","options":["A. G34","B. G35","C. G36","D. G37"],"answer":"C","explanation":"对：部分系统（如华中）规定G36代表开启“直径编程”模态，G37代表半径编程。错：ABD属于变导程螺纹或特殊功能。记：36直径，37半径。"},{"id":49,"type":"single","category":"数控编程指令","difficulty":2,"question":"G28 X(U)_Z(W)_；中X(U)和Z(W)后面的数值是( )的坐标。","options":["A. 参考点","B. 中间点","C. 目标点","D. 工件原点"],"answer":"B","explanation":"对：G28自动回参考点，为了防沿途撞击，格式规定后方跟的值是先过去的安全过渡“中间点”。错：ACD逻辑错。记：G28后带中间点。"},{"id":50,"type":"single","category":"数控编程指令","difficulty":1,"question":"数控车床中的G41/G42是对（ ）进行补偿。","options":[{"text":"A. 刀具的长度","img":""},{"text":"B. 刀具的刀尖圆弧半径","img":""},{"text":"C. 刀具的角度","img":""},{"text":"D. 刀具的半径","img":""}],"answer":"D","explanation":"G41/G42 的核心功能。通过 D 号指定半径，实现左/右侧补偿。","img":""},{"id":51,"type":"single","category":"数控机床与系统","difficulty":1,"question":"CNC装置由硬件和软件组成，软件在( )的支持下运行。","options":["A. 硬件","B. 存储器","C. 显示器","D. 程序"],"answer":"A","explanation":"对：任何控制逻辑、算法软件必须依托物理芯片硬件底层运行环境。错：BCD属于局部器件或运行数据。记：程序由硬核支撑运行。"},{"id":52,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"感应同步器是一种（ ）位置检测元件。","options":["A. 光学式","B. 电磁式","C. 数字式","D. 增量式"],"answer":"B","explanation":"对：感应同步器基于定滑尺之间的电磁耦合感应工作，属于电磁感应检测。错：光栅才是光学。记：感应互感即电磁。"},{"id":53,"type":"single","category":"检测与伺服系统","difficulty":1,"question":"数控机床的进给系统由NC发出指令，通过伺服系统最终由( )来完成坐标轴的移动。","options":["A. 电磁阀","B. 伺服电机","C. 变压器","D. 测量装置"],"answer":"B","explanation":"对：伺服电机是把电流能量最终转化为机械能并拖动坐标轴运动的物理源。错：ACD无拖动轴进给功用。记：进给动力靠电机。"},{"id":54,"type":"single","category":"数控编程指令","difficulty":1,"question":"在XY坐标平面内进行加工的坐标指令是（ ）。","options":["A. G17","B. G18","C. G19","D. G20"],"answer":"A","explanation":"对：G17选择XY平面，G18是ZX平面，G19是YZ平面。错：BCD不符规定。记：17XY，18ZX，19YZ。"},{"id":55,"type":"single","category":"数控编程指令","difficulty":2,"question":"在加工整圆时，应采用哪一种方式进行编程( )","options":["A. 角度加半径","B. 极坐标圆弧插补","C. 插补参数I.J.K","D. 前面几种均可"],"answer":"C","explanation":"对：由于起终点重合，R无法定唯一圆心，标准数控硬性要求整圆必须使用I、J、K来指定圆心坐标。错：AB无法实现整圆编程。记：整圆必须找IJK。"},{"id":56,"type":"single","category":"数控机床与系统","difficulty":1,"question":" CNC系统中的PLC是（ ）。","options":["A. 多微处理器","B. 环形分配器","C. 显示器","D. 可编程序逻辑控制器"],"answer":"D","explanation":"对：PLC英文全称为Programmable Logic Controller（可编程序逻辑控制器），负责辅助开关控制。错：ABC错乱概念。记：PLC即是可编程逻辑控制。"},{"id":57,"type":"single","category":"数控加工工艺","difficulty":2,"question":"铣削封闭的内轮廓表面时，进刀方式应选择（ ）切入","options":["A. 圆弧","B. 法向","C. 根据需要选择A或B","D. 无正确答案"],"answer":"A","explanation":"对：切向圆弧切入最平滑，进给抗力小，防出现垂向刀痕。错：法向会由于瞬间应力垂直砸出切削深痕。记：洗内孔圆弧切入最平稳。"},{"id":58,"type":"single","category":"数控编程指令","difficulty":1,"question":"以下辅助功能代码中常用于作为主程序结束的代码是（ ）。","options":["A. M30","B. M05","C. M01","D. M00"],"answer":"A","explanation":"对：M30既代表结束切削程序，还自带强行令光标重置回首行的功能。错：M05主轴停，M00程序暂停。记：主程序收尾复位用M30。"},{"id":59,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"下列哪种检测元件，不属于位置检测元件（ ）","options":["A. 测速发电机","B. 旋转变压器","C. 编码器","D. 光栅"],"answer":"A","explanation":"对：测速发电机输出电压正比于转速，是专职的速度测定元件，不测位移。错：BCD均是通用测角或直线位移的位置传感器。记：测速不测位，速度发电机落选。"},{"id":60,"type":"single","category":"数控编程指令","difficulty":2,"question":"下例指令中属于非模态的G功能指令是（ ）。","options":["A. G03","B. G04","C. G17","D. G32"],"answer":"B","explanation":"对：G04（暂停延时）仅在其书写的当前程序行有效一次。错：ACD全属于可在下文多行持续沿用的模态代码。记：G04单次生效不延续。"},{"id":61,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"步进电机的转角，转速，旋转方向分别与（ ）有关。","options":["A. 输入脉冲的个数.频率.通电顺序。","B. 输入脉冲频率.个数.通电顺序能力","C. 输入脉冲频率.通电顺序.脉冲个数。","D. 通电顺序.输入脉冲频率.个数。"],"answer":"A","explanation":"对：发了几个脉冲对应转几度，频率高低对应转轴快慢，通电励磁相序决定转向。错：BCD要素配对混乱。记：脉数看位置，频率看快慢，相序看方向。"},{"id":62,"type":"single","category":"数控编程指令","difficulty":2,"question":"在编制加工程序时，如需加延时的单位是秒，准备功能G04后跟着相对应地址是（ ）。","options":["A. C","B. S","C. F","D. X"],"answer":"D","explanation":"对：G04 X_ 后直接跟带有小数点的延时秒数值（如G04 X2.5）。错：ABC并非暂停地址码。记：暂停延时找G04 X。"},{"id":63,"type":"single","category":"数控机床与系统","difficulty":1,"question":"数控机床是采用数字化信号对机床的（ ）进行控制。","options":["A. 运动","B. 加工过程","C. 运动和加工过程","D. 无正确答案"],"answer":"C","explanation":"对：数控不仅用数字脉冲精确控制进给轴几何联动，还同步调度开关等加工过程。错：AB叙述单薄。记：两手抓，控制运动配过程。"},{"id":64,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"位置检测装置按测量的方式分为（ ）。","options":["A. 数字式和模拟式","B. 增量式和绝对式","C. 直接和间接","D. 回转型和直线型"],"answer":"B","explanation":"对：依位移测量读数基准形式，分为从当前累加的增量型和带独立格码识别的绝对型。错：A按信号分，C按位置分。记：读数方式看增量绝对。"},{"id":65,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"光栅中，标尺光栅与指示光栅的栅线应：（ ）","options":["A. 相互平行","B. 互相倾斜一个很小的角度","C. 互相倾斜一个很大的角度","D. 外于任意位置均可"],"answer":"B","explanation":"对：两块光栅刻线间需维持微小交错夹角，方可形成带光学放大效能的莫尔条纹。错：若平行则无莫尔条纹。记：微小斜角才能出莫尔条纹。"},{"id":66,"type":"single","category":"数控编程指令","difficulty":1,"question":"子程序结束的程序代码是（ ）。","options":["A. M01","B. M02","C. M98","D. M99"],"answer":"D","explanation":"对：M99用来标志当前运行的子程序结束返回主程序行。错：M98是启动调用代码。记：98命令去调用，99干完打道回府。"},{"id":67,"type":"single","category":"检测与伺服系统","difficulty":1,"question":"下列哪种伺服系统的精度最高：（ ）","options":["A. 开环伺服系统","B. 闭环伺服系统","C. 半闭环伺服系统","D. 闭环.半闭环系统"],"answer":"B","explanation":"对：全闭环系统反馈光栅直接锁死工作台，根除了传动链累积背隙差，精度至高。错：AC精度被机械摩擦与丝杠拖累。记：最准还是全闭环。"},{"id":68,"type":"single","category":"数控机床与系统","difficulty":2,"question":"在数控机床上，确定坐标轴的先后顺序为（ ）。","options":["A. X轴—Y轴—Z轴","B. X轴—Z轴—Y轴","C. Z轴—X轴—Y轴","D. Z轴—Y轴—X轴"],"answer":"C","explanation":"对：标准体系首先定出平行动力主轴的Z轴，接着确定水平长进给X轴，最后据右手法则得出Y轴。错：ABD颠倒顺序。记：先Z、再X、最后得出Y。"},{"id":69,"type":"single","category":"插补与控制原理","difficulty":2,"question":"在CNC系统中，插补功能的实现通常采用：( )","options":["A. 全部硬件实现","B. 粗插补由软件实现，精插补由硬件实现","C. 粗插补由硬件实现，精插补由软件实现","D. 无正确答案"],"answer":"B","explanation":"对：主流架构为求兼顾灵活性与高速输出，用软件算法跑大周期的粗插补，硬件电路执行精细的高频细分脉冲。错：AC分配错误。记：软粗硬精效益高。"},{"id":70,"type":"single","category":"数控编程指令","difficulty":1,"question":"下面哪种是程序段号的正确表达方式（ ）。","options":["A. N0001","B. O0001","C. P0001","D. X0001"],"answer":"A","explanation":"对：N代表程序行编号（Block Number）。错：O代表总主程序号，P用于循环，X是坐标轴。记：N后跟随是行号。"},{"id":71,"type":"single","category":"数控编程指令","difficulty":2,"question":"刀具暂停的正确指令形式为( )。","options":["A. G04 X1.0","B. G04 P1000","C. A.B均正确","D. 无正确答案"],"answer":"C","explanation":"对：G04支持X带小数点秒，或P代表不带小数点的无符号整数毫秒（1000ms=1s），二者等效有效。错：AB单选错。记：X带点秒，P是无点毫秒。"},{"id":72,"type":"single","category":"数控编程指令","difficulty":2,"question":"采用半径编程方法编写圆弧插补程序时，当其圆弧所对圆心角( )180°小于360°时，该半径R取负值。","options":["A. 大于","B. 小于","C. 小于等于","D. 大于等于"],"answer":"A","explanation":"对：半径R形式描述圆弧时，若圆心角 $> 180^{\\\\circ}$ 且 $< 360^{\\\\circ}$，半径R前必须强加负号区别劣弧。错：BCD违反规则。记：大弧取负正取小。"},{"id":73,"type":"single","category":"数控加工工艺","difficulty":2,"question":"下列哪种加工过程会产生过切削现象。( )","options":["A. 加工半径小于刀具半径的内圆弧","B. 被铣削槽底宽小于刀具直径","C. 加工比此刀具半径小的台阶","D. 以上均正确"],"answer":"D","explanation":"对：当工件内壁曲线或几何开槽极限小于选定的物理刀具外缘半径时，切削刀具定会铲掉邻近多余肉厚。错：ABC单列过切。记：坑小刀大必切多。"},{"id":74,"type":"single","category":"数控编程指令","difficulty":1,"question":"FANUC系统中，在主程序中调用子程O2000，其正确的指令是（ ）。","options":["A. M98O2000","B. M99O2000","C. M98P2000","D. M99P2000"],"answer":"C","explanation":"对：法那克调用子程序规定使用M98代码，后面通过P指出要调用的四位子程序代号。错：M99是子程序收尾。记：M98 P调子程。"},{"id":75,"type":"single","category":"数控机床与系统","difficulty":1,"question":"下列哪种机床不属于点位控制数控机床。( )","options":["A. 数控钻床","B. 坐标镗床","C. 数控冲床","D. 数控车床"],"answer":"D","explanation":"对：数控车床切削面是在连续进给受控中切出的，属于轮廓联动控制。错：ABC定位期间不切削，点到切削。记：车床全盘切外圆，必属于轮廓控。"},{"id":76,"type":"single","category":"数控编程指令","difficulty":1,"question":"可用作直线插补的准备功能代码是（ ）。","options":["A. G03","B. G02","C. G01","D. G04"],"answer":"C","explanation":"对：G01代码指派各轴联合执行直线轨迹受控切削运动。错：G02/G03属于圆弧控制。记：直线行进用G01。"},{"id":77,"type":"single","category":"数控编程指令","difficulty":2,"question":"某一段程序 N70 G00 G54 G90 X100 Y100 Z80；N80 G01 X80 Z50 F100；执行完第 N80 段之后，机床到达工件坐标点为( )。","options":["A. X=100，Y=100，Z=80","B. X=80，Y=100，Z=50","C. X=100 overnight ，Y=0， Z=50","D. X=80，Y=0，Z=50"],"answer":"B","explanation":"对：G90是绝对坐标值模式。N80行内缺省未写Y值，表明Y沿用并维持前行的模态值100。错：CD误把未写写成了清零。记：未声明的轴原地不动。"},{"id":78,"type":"single","category":"数控编程指令","difficulty":1,"question":"取消刀具长度补偿的G代码是（ ）。","options":["A. G42","B. G43","C. G44","D. G49"],"answer":"D","explanation":"对：G49用来清除撤销当前运行的Z轴刀具长度正负向偏置。错：G43/G44是长度正负激活。记：49清空长度补。"},{"id":79,"type":"single","category":"插补与控制原理","difficulty":2,"question":"一直线的起点坐标在坐标原点，终点坐标为 A（xa.ya），刀具的坐标为 P（x.y）。用逐点比较法对该直线进行插补时的偏差函数是（ ）。","options":["A. F＝x·y－xa·ya","B. F＝xa·y－ya·x","C. F＝xa·x－ya·y","D. F＝xa+ya－x－y"],"answer":"B","explanation":"对：第一象限直线段偏差几何算式是终点坐标与当前点有向交叉乘减：$F = x_a \\\\cdot y - y_a \\\\cdot x$。错：ACD不符算式定义。记：斜率公式两端交叉乘。"},{"id":80,"type":"single","category":"数控编程指令","difficulty":1,"question":" M05 表示( )。","options":["A. 冷却液开","B. 冷却液关","C. 夹紧","D. 主轴停止"],"answer":"D","explanation":"对：M05控制开关跳闸主轴切削动力输出。错：M03是正转，08/09管水泵。记：03正转05停。"},{"id":81,"type":"single","category":"数控编程指令","difficulty":1,"question":"可用作直线插补的准备功能代码是（ ）。","options":["A. G01","B. G02","C. G03","D. G04"],"answer":"A","explanation":"对：G01实现受控直线切削移动。错：同第76题。记：经典复刻，直线必定找G01。"},{"id":82,"type":"single","category":"数控编程指令","difficulty":2,"question":"在固定循环指令格式G90 G98 G73 X＿Y＿R＿Z＿Q＿F＿;其中R表示（ ）。","options":["A. 孔深","B. 每次进刀深度","C. 参考平面高度","D. 孔位置"],"answer":"C","explanation":"对：固定循环格式中，R专用指定快定位下刀到的接近安全“参考平面高度位置”。错：Z指孔底，Q指单次进深。记：循环内R代表快速下刀参考面。"},{"id":83,"type":"single","category":"数控编程指令","difficulty":1,"question":"程序加工完成后，程序复位，光标能自动回到起始位置的指令是（ ）。","options":["A. M00","B. M01","C. M02","D. M30"],"answer":"D","explanation":"对：M30通知系统加工完毕并强令代码处理堆栈指针归回首行。错：M02无强制归首行机制。记：产线连续加工用M30。"},{"id":84,"type":"single","category":"数控编程指令","difficulty":2,"question":"下列代码指令中，在程序里可以省略、次序颠倒的地址符是（ ）。","options":["A. O","B. G","C. N","D. M"],"answer":"C","explanation":"对：N（行号）对于指令编译核没有实质运动约束，可以打乱或全局省略不写。错：ABD缺失会导致编译崩溃。记：行号N写不写随你意。"},{"id":85,"type":"single","category":"检测与伺服系统","difficulty":2,"question":"直流伺服电动要适用于（ ）伺服系统中。","options":["A. 开环、闭环","B. 开环、半闭环","C. 闭环、半闭环","D. 开环"],"answer":"C","explanation":"对：伺服电机必须基于反馈元件来实施精度调节，构筑成闭环或半闭环系统。错：开环只搭载步进电机。记：伺服出场必是反馈（闭/半闭）。"},{"id":86,"type":"single","category":"数控机床与系统","difficulty":1,"question":"数控系统的核心是（ ）。","options":["A. 输入装置","B. 数控装置","C. 伺服系统","D. 机床本体"],"answer":"B","explanation":"对：数控装置（CNC）控制硬件承载数据计算，是处理的核心中枢。错：ACD为外部输入或机械机体机构。记：系统核心认准数控装置。"},{"id":87,"type":"single","category":"数控编程指令","difficulty":2,"question":"以下G指令中用于建立镜像功能的是（ ）。","options":["A. G24","B. G25","C. G68","D. G69"],"answer":"A","explanation":"对：铣床规定G24用于调用并开启坐标系对称“镜像”转换。错：G25属于撤销镜像，G68/G69是旋转。记：24开启镜像。"},{"id":88,"type":"single","category":"数控编程指令","difficulty":1,"question":"以下G指令中用于螺纹车削的是（ ）。","options":["A. G32","B. G90","C. G91","D. G80"],"answer":"A","explanation":"对：G32是外圆单一、等螺距长螺纹的专用切削插补指令。错：BCD不符指令功用。记：切削单刀螺纹用G32。"},{"id":89,"type":"single","category":"数控编程指令","difficulty":1,"question":"M指令主要用于控制机床的各种开关，其中M05表示（ ）。","options":["A. 主轴正转","B. 主轴反转","C. 主轴停转","D. 程序停止"],"answer":"C","explanation":"对：控制主轴断油断电停转。错：同第80题变体。记：05强制主轴停。"},{"id":90,"type":"judge","category":"数控编程指令","difficulty":2,"question":"在具有旋转功能的程序中刀具半径补偿的建立必须在旋转前进行。（ ）","options":[],"answer":false,"explanation":"错：半径补偿可在旋转（G68）生效后建立，不强制要求在旋转指令前执行。"},{"id":91,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"由加工设备.物流系统和信息系统三部分组成的高度自动化和高度柔性化制造系统，简称为FMS。（ ）","options":[],"answer":true,"explanation":"对：完全对应多台加工设备加智能传送线及总信息主控组成的柔性系统。"},{"id":92,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"在数控机床坐标系中，规定传递切削动力的主轴轴线为Y坐标轴。（ ）","options":[],"answer":false,"explanation":"错：传递主要切削力旋转的主轴轴线，任何标准下都硬性定死为Z坐标轴。"},{"id":93,"type":"judge","category":"数控机床与系统","difficulty":2,"question":"机床的参考原点就是移动轴的测量起点，可以与机床原点重合。（ ）","options":[],"answer":true,"explanation":"结论：该说法是正确的。\\n在数控机床中，参考原点（Reference Point） 确实是用于建立坐标系的测量起点，且通常情况下它可以与 机床原点（Machine Zero） 重合。","img":""},{"id":94,"type":"judge","category":"数控编程指令","difficulty":2,"question":"刀具半径补偿的建立和撤消要和移动类指令配合使用，如 G00.G01.G02. G03 等。（ ）","options":[],"answer":false,"explanation":"错：错误在于带了圆弧指令。补偿偏置计算必须在G00或G01直线移动行才能安全转换。"},{"id":95,"type":"judge","category":"检测与伺服系统","difficulty":1,"question":"在闭环系统中，光栅传感器可用于检测运动件的直线位移量。（ ）","options":[],"answer":true,"explanation":"对：直线光栅尺的作用就是通过光电栅线计数直接量取导轨滑块移动的总位移。"},{"id":96,"type":"judge","category":"插补与控制原理","difficulty":1,"question":"所谓 “ 插补 ” 就是将已知的数据点进行 “ 密化 ” 的过程。（ ）","options":[],"answer":true,"explanation":"对：插补就是在离散的图纸起终点之间通过高密度的计算坐标串实施轨迹“密化”。"},{"id":97,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"根据 ISO 标准，在编程时采用刀具相对静止而工件运动规则。（ ）","options":[],"answer":false,"explanation":"错：规定相反。标准假定“工件绝对静止绑定，运动全部源自刀具的移动路径”。"},{"id":98,"type":"judge","category":"插补与控制原理","difficulty":2,"question":"脉冲增量法插补和数据采样法插补输出的都是脉冲。（ ）","options":[],"answer":false,"explanation":"错：数据采样法输出的是闭环位置寄存器的数值量（坐标偏置），并非数字高低电平物理脉冲。"},{"id":99,"type":"judge","category":"数控编程指令","difficulty":1,"question":"在 G55中设置的数值是工件坐标系的原点。（ ）","options":[],"answer":true,"explanation":"对：G55中输入的空间数值即代表第二个工件零点相对机械零点的坐标间距。"},{"id":100,"type":"judge","category":"数控编程指令","difficulty":2,"question":"与B刀补相比，C刀补的加工精度更高。（ ）","options":[],"answer":true,"explanation":"对：C刀补有超前预测多行读入能力，能根除拐弯衔接的尖角过切，精度更高。"},{"id":101,"type":"judge","category":"数控编程指令","difficulty":1,"question":"移动类指令，如 G00.G01. G02. G03 等，不可以相互注销。（ ）","options":[],"answer":false,"explanation":"错：它们全在一组模态代码内，写了当前行会自动覆盖并注销上一行的运动模态。"},{"id":102,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"所有的数控机床都设有检测装置。（ ）","options":[],"answer":false,"explanation":"错：使用步进电机控制的简易开环机床完全不需要、也没有装配位置反馈检测元件。"},{"id":103,"type":"judge","category":"数控编程指令","difficulty":1,"question":"进给速度单位的设定指令 G94为每转进给，指令 G95 为每分钟进给。（ ）","options":[],"answer":false,"explanation":"错：说反了。G94是每分钟毫米数（mm/min），G95代表的是每转毫米数（mm/r）。"},{"id":104,"type":"judge","category":"数控编程指令","difficulty":1,"question":"机床原点 and 工件原点都是人为设定的。（ ）","options":[],"answer":false,"explanation":"错：工件原点是人选的，但机床原点是出厂装配时硬性定死在刚性物理架构上的。"},{"id":105,"type":"judge","category":"数控编程指令","difficulty":2,"question":"零件加工程序由若干程序段组成， 一个程序段各代码字的顺序都有严格规定， 不能随意调换（ ）","options":[],"answer":false,"explanation":"错：只要地址符无误且在一行之内，G、X、M等排版的前后次序并不会阻碍系统识别。"},{"id":106,"type":"judge","category":"插补与控制原理","difficulty":2,"question":"对于不同象限.不同走向的圆弧插补时，可以用同一个公式计算偏差值，但坐标轴的进给方向不同。（ ）","options":[],"answer":true,"explanation":"对：通过数学变换，四个象限的圆弧可以合并为统一的偏差计算式，动作仅由进给电机换向体现。"},{"id":107,"type":"judge","category":"数控编程指令","difficulty":2,"question":"G92所设定的加工坐标原点是与当前刀具所在位置无关。（ ）","options":[],"answer":false,"explanation":"错：G92设定工件系是彻底根据刀具“当前的物理停留点位置”倒推设定的，息息向连。"},{"id":108,"type":"judge","category":"数控编程指令","difficulty":1,"question":"G92 X_Y_Z_ 使机床不产生任何运动。( )","options":[],"answer":true,"explanation":"对：G92只是一句对CPU寄存器进行数据改写的赋值定位指令，坐标轴绝不运动。"},{"id":109,"type":"judge","category":"数控加工工艺","difficulty":1,"question":"数控机床的加工工艺与普通机床没有区别。（ ）","options":[],"answer":false,"explanation":"错：数控对刚性要求高，工艺多道集中，进刀路线、刀补偏置考虑多，繁琐深入得多。"},{"id":110,"type":"judge","category":"数控编程指令","difficulty":2,"question":"圆弧加工指令 G02/G03中的信息字 I .J 是指圆弧起点相对于圆弧圆心的增量坐标。（ ）","options":[],"answer":true,"explanation":"对：标准规定I、J是圆弧起点有向指向圆弧几何中心的各坐标轴坐标相对差值。"},{"id":111,"type":"judge","category":"数控加工工艺","difficulty":1,"question":"精加工时的切削用量比粗加工时小。（ ）","options":[],"answer":true,"explanation":"对：精加工需确保光洁度与尺寸界限，其吃刀深、进给用量都远小于粗加工。"},{"id":112,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"数控铣床与加工中心相比， 加工中心是一种备有刀库并能自动更换刀具， 对工件进行多工序加工的数控机床。( )","options":[],"answer":true,"explanation":"对：两者的分水岭就是加工中心配置了全自动机械手以及容纳多把刀具的旋转刀库。"},{"id":113,"type":"judge","category":"数控编程指令","difficulty":1,"question":"G00程序段中必须给出进给速度。（ ）","options":[],"answer":false,"explanation":"错：G00为高速空程定位，其速度读取自系统底层设定的最大硬件极限，程序无需写F。"},{"id":114,"type":"judge","category":"数控编程指令","difficulty":1,"question":"在 FANUC系统中，规定用 M04指令换刀。( )","options":[],"answer":false,"explanation":"错：法那克换刀依靠T加M06进行。M04指令含义代表的是主轴逆时针反转。"},{"id":115,"type":"judge","category":"数控机床与系统","difficulty":2,"question":"为提高机床运动的灵敏度和低速运动的平稳性，精密数控机床的导轨常采用滚动导轨。（ ）","options":[],"answer":true,"explanation":"对：滚动导轨动静摩擦阻力差极小，可杜绝机床低速爬行现象，动作灵敏精准。"},{"id":116,"type":"judge","category":"数控编程指令","difficulty":1,"question":"数控程序的模态指令是指该指令仅只在当前行有效。（ ）","options":[],"answer":false,"explanation":"错：模态代码一经启动将全局延续有效，直到被同组代码覆盖。只在单行有效的叫非模态。"},{"id":117,"type":"judge","category":"检测与伺服系统","difficulty":2,"question":"光栅尺是一种能够间接检测直线位移或角位移的伺服系统反馈元件。( )","options":[],"answer":false,"explanation":"错：光栅尺直接装配在刀架或台体上检测运行尺寸，属于“直接测量元件”。"},{"id":118,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"数控机床开机后，必须先进行返回参考点操作。（ ）","options":[],"answer":true,"explanation":"对：开机必须回零，清除系统断电带来的坐标记忆盲区，找回绝对机械基准。"},{"id":119,"type":"judge","category":"数控加工工艺","difficulty":1,"question":"选择粗加工切削用量时， 首先应选择尽可能大的背吃刀量， 以减少走刀次数。( )","options":[],"answer":true,"explanation":"对：粗加工旨在全力去肉。首要增大背吃刀量（吃刀深）可大幅缩减走刀耗时。"},{"id":120,"type":"judge","category":"数控编程指令","difficulty":2,"question":"与C刀补相比，B刀补的加工精度更高。（ ）","options":[],"answer":false,"explanation":"错：完全弄反。老旧的B刀补没有超前段轨迹纠偏功能，精度和防过切能力差远了。"},{"id":121,"type":"judge","category":"数控编程指令","difficulty":2,"question":"机床的原点就是机械零点，编制程序时必须考虑机床的原点。（ ）","options":[],"answer":false,"explanation":"错：编程直接使用“工件原点”写尺寸即可，底层转换交给系统，编程无需考虑机械零位。"},{"id":122,"type":"judge","category":"数控编程指令","difficulty":2,"question":"使用G71粗加工时，在ns-nf程序段中的F.S.T是无效的。（ ）","options":[],"answer":true,"explanation":"对：执行G71纵向大刀去肉期间，ns-nf行内的工艺值被全面屏蔽，只对后期精车G70生效。"},{"id":123,"type":"judge","category":"插补与控制原理","difficulty":2,"question":"逐步比较插补法的四拍工作顺序为终点判别. 偏差判别. 进给控制. 新偏差计算。（ ）","options":[],"answer":false,"explanation":"错：时序错乱。第一步必须先针对位置做‘偏差判别’，不能先判别终点。见第1题。"},{"id":124,"type":"judge","category":"数控编程指令","difficulty":2,"question":"螺纹指令G32X41W-43F2;是以每分钟2mm的速度加工螺纹。（ ）","options":[],"answer":false,"explanation":"错：螺纹切削段内的F代表导程。表明主轴转一圈轴向进给2mm，非固定每分钟速度。"},{"id":125,"type":"judge","category":"数控编程指令","difficulty":2,"question":"刀具位置补偿值就是刀具半径补偿值。（ ）","options":[],"answer":false,"explanation":"错：位置补偿指刀尖几何对齐和磨损偏置；半径补偿是应对外轮廓防止过切的平移量。"},{"id":126,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"数控机床的坐标系采用的是右手笛卡儿直角坐标系。（ ）","options":[],"answer":true,"explanation":"对：国家与ISO标准硬性指定三维直线笛卡儿轴系运动律。"},{"id":127,"type":"judge","category":"插补与控制原理","difficulty":2,"question":"数控机床常用的脉冲当量有 1mm/脉冲. 0.001mm/脉冲. 0.01mm/脉冲等。（ ）","options":[],"answer":false,"explanation":"错：1mm/脉冲当量移动由于分辨率极其粗糙，无法在真实数控工业精度下应用。"},{"id":128,"type":"judge","category":"检测与伺服系统","difficulty":1,"question":"步进电动机伺服系统是典型的闭环伺服系统。（ ）","options":[],"answer":false,"explanation":"错：步进电机系统不配置任何末端检测尺反馈校正，属于经典“开环控制”。"},{"id":129,"type":"judge","category":"检测与伺服系统","difficulty":2,"question":"半闭环控制系统中的检测元件接在机床运动部件上。（ ）","options":[],"answer":false,"explanation":"错：半闭环光电元件是接在丝杠端或电机尾巴上，接到运动部件本体（工作台）的是全闭环。"},{"id":130,"type":"judge","category":"检测与伺服系统","difficulty":2,"question":"直流伺服电机的调速特性不如交流伺服电机。（ ）","options":[],"answer":false,"explanation":"错：直流伺服调速品质极其线性平滑，只因电刷易碳化磨损维护高，才逐渐退出舞台。"},{"id":131,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"数控机床的运动方向的规定，某一部件运动的正方向是工件远离刀具的方向。（ ）","options":[],"answer":false,"explanation":"错：概念记反。标准指定正坐标方向恒为“刀具相对远离工件实体”的轴运动进给方向。"},{"id":132,"type":"judge","category":"检测与伺服系统","difficulty":1,"question":"旋转变压器主要是利用电磁感应原理工作的。（ ）","options":[],"answer":true,"explanation":"对：旋转变压器是依赖定转子电磁线圈互感输出的电压相对相位来测定角位移的。"},{"id":133,"type":"judge","category":"数控加工工艺","difficulty":1,"question":"在数控机床上加工一批零件，只需进行一次对刀操作。（ ）","options":[],"answer":false,"explanation":"错：加工期间如遭遇到切削刀刃破损更换新刀具、机械意外撞击、改动装夹时，必须再对刀。"},{"id":134,"type":"judge","category":"数控编程指令","difficulty":2,"question":"G54~G59是系统预置的6个坐标系，使用该组指令前，必须先回参考点（ ）","options":[],"answer":true,"explanation":"对：G54~G59是与机械坐标强关联的，如果不先回零，系统无法获取绝对位置换算偏置。"},{"id":135,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"“机床原点 ” 是指机床上一个任意指定的点。（ ）","options":[],"answer":false,"explanation":"错：机床原点是全系统底层唯一的绝对零位基准点，由生产装配厂家精准焊制定死。"},{"id":136,"type":"judge","category":"数控编程指令","difficulty":1,"question":"用半径R形式指令圆心位置时，不能描述整圆。（ ）","options":[],"answer":true,"explanation":"对：当终点回归到起点时，圆心位置解具有无穷多，R会造成编译解计算死循环歧义。"},{"id":137,"type":"judge","category":"数控编程指令","difficulty":2,"question":"顺时针圆弧插补(G02)和逆时针圆弧插补(G03)的判别方向是：沿着不在圆弧平面内的坐标轴正方向向负方向看去，顺时针方向为G02，逆时针方向为G03。 ( )","options":[],"answer":true,"explanation":"对：符合标准平面圆弧方向判断定则（如在XY平面看，需沿Z轴正方向往负方向俯视）。"},{"id":138,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"数控机床的坐标运动是指工件相对于静止的刀具的运动。 ( )","options":[],"answer":false,"explanation":"错：与第97题同理。为简化编程思想，恒定假定“工件钉死静止，所有进给均为刀具相对运动”。"},{"id":139,"type":"judge","category":"数控加工工艺","difficulty":2,"question":"为保证工件轮廓表面粗糙度，最终轮廓应在一次走刀中连续加工出来。（ ）","options":[],"answer":true,"explanation":"对：在精车轮廓中途若发生中断接刀、停顿，会因切削应力卸载与突变留下台阶刀痕。"},{"id":140,"type":"judge","category":"数控机床与系统","difficulty":1,"question":"数控机床的坐标系采用右手法则判定 X、Y、Z 的方向。（ ）","options":[],"answer":true,"explanation":"对：完全契合标准右手空间正交直角系空间法则。见第34与126题。"},{"id":141,"type":"judge","category":"数控编程指令","difficulty":1,"question":"程序原点又称为起刀点。（ ）","options":[],"answer":false,"explanation":"错：程序原点是坐标中心(0,0)；起刀点是刀具运动加工前，物理停靠就绪的停留空间位置。"},{"id":142,"type":"judge","category":"数控编程指令","difficulty":2,"question":"在同一程序段中，绝对编程和增量编程二者可以混合编程。（ ）","options":[],"answer":true,"explanation":"在同一程序段中绝对编程（Absolute Programming）和增量编程（Incremental Programming）是可以混合使用的。\\n虽然早期或部分特定型号（如 Fanuc 控制器）可能存在限制，但随着技术发展，混合坐标编程已成为常规操作，以提高编程效率和灵活性。","img":""},{"id":143,"type":"essay","category":"简答题","difficulty":2,"question":"数控机床有哪几种分类方法？各有什么特点？","options":[],"answer":"# 数控机床分类总结\\n1. **按工艺用途**\\n- 金属切削类：车铣中心，去料、精度高\\n- 金属成型类：折弯冲床，板材成型\\n- 特种加工类：电火花线切割，适配异形、高硬度工件\\n\\n2. **按运动轨迹**\\n- 点位控制：仅精准定位，移动中不切削\\n- 直线控制：刀具单轴直线切削\\n- 轮廓控制：多轴联动，可切削任意曲线\\n\\n3. **按伺服控制**\\n- 开环：步进电机、无反馈，结构简单、成本低、精度差\\n- 半闭环：丝杠端检测，性能稳定、性价比高\\n- 闭环：工作台配光栅，精度顶尖、结构复杂、造价高","explanation":"","img":""},{"id":144,"type":"essay","category":"简答题","difficulty":2,"question":"画出闭环数控系统的框图，与开环系统相比有何特点？","options":[],"answer":"对比开环系统特点：\\n1. 闭环系统具有由光栅测量元件组成的位置全闭环负反馈回路，开环则完全没有反馈监控。\\n2. 闭环控制精度极大领先，能全自动检测并补偿传动丝杠的反向死区及传动背隙误差；开环精度低，重载易丢步。\\n3. 闭环系统调试技术门槛高，由于反馈延迟易发生震荡，机械及硬件价格昂贵；开环机械简单、划算。","img":"","explanation":"","answerImg":"https://cdn.jsdu.cn/opdav/20260609/d9aadab467ba4a19eaa0cddc96770eef.png"},{"id":145,"type":"essay","category":"简答题","difficulty":3,"question":"有一直线光栅，每毫米刻线数为100，主光栅与指示光栅的夹角θ=0.005rad，则莫尔条纹的栅距W，节距B分别是多少？光栅栅距被放大了多少倍？","options":[],"answer":"已知 $n = 100$，$\\\\theta = 0.005 \\\\text{ rad}$。\\n光栅节距 $W = \\\\frac{1}{n} = \\\\frac{1}{100} = 0.01 \\\\text{ mm}$\\n莫尔条纹间距 $B = \\\\frac{W}{\\\\theta} = \\\\frac{0.01}{0.005} = 2 \\\\text{ mm}$\\n放大倍数 $K = \\\\frac{B}{W} = \\\\frac{2}{0.01} = 200$\\n答：光栅节距W为0.01mm，莫尔条纹间距B为2mm，光栅栅距被放大了200倍。","explanation":"核心精要：节距为刻线数的倒数；莫尔条纹宽度等于节距除以夹角弧度；放大倍数则是夹角数值的倒数。","img":"","answerImg":""},{"id":146,"type":"essay","category":"简答题","difficulty":3,"question":"请写出复合循环指令G71、G72和G73的指令格式，并说明各地址符的含义。","options":[],"answer":"以常用标准 FANUC 系统格式为例：\\n1. G71 外圆/内孔纵向粗车复合循环：\\n   `G71 U(Δd) R(e);` `G71 P(ns) Q(nf) U(Δu) W(Δw) F_ S_ T_;` \\n   含义：Δd表示径向每次吃刀深度（半径值）；e表示单次退刀量；ns至nf表示轮廓程序起始与结束行号；Δu表示X轴精车预留余量（直径值）；Δw表示Z轴精车留量。\\n2. G72 端面横向粗车复合循环：\\n   `G72 W(Δd) R(e);` `G72 P(ns) Q(nf) U(Δu) W(Δw) F_ S_ T_;` \\n   含义：Δd表示Z轴方向每次吃刀深度；其余各项地址符技术含义与G71一致，区别仅在于进刀路径平行于直径轴。\\n3. G73 封闭轮廓仿形粗车复合循环：\\n   `G73 U(Δi) W(Δk) R(d);` `G73 P(ns) Q(nf) U(Δu) W(Δw) F_ S_ T_;` \\n   含义：Δi表示X轴方向总粗车去除量（半径值）；Δk表示Z轴方向总粗车留量；d表示该循环切削的总分摊次数。"},{"id":147,"type":"essay","category":"简答题","difficulty":2,"question":"已知一个转子齿数为40.三相六拍工作方式的步进电机，试计算其步距角的大小。","options":[],"answer":"### 公式与计算\\n步进电机**三相六拍**步距角公式：\\n$$\\\\alpha = \\\\frac{360^\\\\circ}{m \\\\cdot z \\\\cdot k}$$\\n- $m=3$（相数），$z=40$（转子齿数），$k=2$（拍数/相数，六拍$k=6/3=2$）\\n\\n\\n$$\\\\alpha = \\\\frac{360^\\\\circ}{3 \\\\times 40 \\\\times 2} = \\\\boldsymbol{1.5^\\\\circ}$$\\n\\n**结论**：步距角为 $\\\\boldsymbol{1.5^\\\\circ}$。","explanation":"口诀要点：步距角等于一周360度除以（转子总齿数乘通电总拍数）。六拍对应的N直接代入6即可。","img":"","answerImg":""},{"id":148,"type":"essay","category":"简答题","difficulty":2,"question":"简述数控车床试切对刀的方法步骤。","options":[],"answer":"1. X轴对刀操作（确立外圆基准）：手动控制主轴切削一段工件外圆，保持X轴绝对不动，沿Z向将刀退离工件。停机测量车削后的外圆直径尺寸，记为 $D$。进入刀补偏置页面，将光标定位在对应刀号的X栏，输入‘X $D$’按测量。系统自动对齐X原点。\\n2. Z轴对刀操作（确立右端零点）：手动驱动主轴切削工件右端面，保持Z轴绝对不动，沿X向退离。在刀补页对应的Z栏内输入‘Z 0’点击测量。此时工件Z轴坐标原点成功绑定零件端面。","explanation":"简练记法：车外圆退Z轴，量直径输X值；轻车端面退X轴，原点定位输Z零。量哪个轴，另一个轴绝不可乱动。"},{"id":149,"type":"essay","category":"简答题","difficulty":2,"question":"简述什么是机床原点、编程原点和参考原点？","options":[],"answer":"1. 机床原点：是设备物理结构上一个恒定唯一的几何原点，由厂家制造装配阶段精想定死，是所有进给坐标运动的总根基，不能更改。\\n2. 编程原点（工件原点）：是技术人员看零件图编程时，为了计算省事在工件实体上人为选定的零点。常选于零件的设计、工艺基准中心处。\\n3. 参考原点（机床参考点）：是带零位行程探测开关的极限档块停留位置。每次机床开机强制执行回零（回参考点）后，数控内核方能最终激活坐标系。"},{"id":150,"type":"essay","category":"简答题","difficulty":2,"question":"数控铣床加工中，刀具半径补偿包括哪些内容？分别用什么指令实现？","options":[],"answer":"主要包含三个完整执行环节：\\n1. 建立半径补偿环节：刀具由安全点直线驶向轮廓，使其中心轨迹向左或右错开偏置一个铣刀半径。G41激活左偏补偿（顺前进方向看刀在左侧），G42激活右偏补偿（刀在右侧）。\\n2. 半径补偿执行环节：在偏置状态下，系统实时根据D表内输入的刀具半径完成多行轨迹偏置切削计算。\\n3. 取消半径补偿环节：加工完脱离轮廓后，用G40退出偏置模式，使中心重归图纸尺寸。必须在G00或G01直线移动行内建立/撤销。","explanation":"记忆技巧：三步走：41左、42右建立；轮廓连续执行；40到站注销清除。圆弧进退必报警。"},{"id":151,"type":"essay","category":"简答题","difficulty":2,"question":"刀具长度补偿包括哪些内容？分别什么指令实现？","options":[],"answer":"1. 正向长度补偿（G43）：将Z轴程序中的目标运动坐标绝对值加上H表内存储的实际刀偏尺寸，用于补齐偏长距离。格式为 `G43 Z_ H_`。\\n2. 负向长度补偿（G44）：将程序Z轴运动坐标绝对值减去H表里的设定值，执行负偏。格式为 `G44 Z_ H_`。\\n3. 取消长度补偿（G49）：加工换刀前，清除所有当前在运行的Z轴长度补偿偏置，复原机床物理轴线状态。"},{"id":152,"type":"essay","category":"简答题","difficulty":1,"question":"一个完整的数控加工程序一般由哪几个基本部分组成？","options":[],"answer":"由以下三大骨架区块拼装组成：\\n1. 程序号开始段：通常以大写 O 引导四位序号数字（如 O1024），用作主存储文件名以及程序头识别。\\n2. 程序正文主体段：由若干行准备功能、进给控制、换刀开关命令组成的连续数据行块（Block），负责核心加工控制。\\n3. 程序收尾结束段：以专用辅助功能M30或M02单独结行，终止全部机床硬件动作并强行令光标原路返回首行复位。"},{"id":153,"type":"essay","category":"简答题","difficulty":2,"question":"写出螺纹车削固定循环G92的指令格式，并说明各地址符的含义？","options":[],"answer":"标准单刀螺纹循环固定格式为：`G92 X(U)_ Z(W)_ R_ F_;` \\n含义：\\n- X(U)：螺纹当前分层进刀切削终点的绝对直径位置（或相对增量移动量）。\\n- Z(W)：螺纹螺牙加工终点的Z轴绝对轴向总长度位置。\\n- R：切削锥螺纹时，起点与终点螺纹处的半径差值大小。加工直螺纹时必须省略不写。\\n- F：该加工螺纹的理论几何导程值（单头螺纹即代表其螺距）。","explanation":"记忆公式：G92四要素：X管外径，Z管长度，R控锥度，F导程带路。多刀车削只需重复递减修改下一行的X值即可。","img":""},{"id":154,"type":"code","category":"程序设计","difficulty":3,"question":"1.使用G71复合循环编写下图外圆阶梯零件车削程序。毛坯为外径φ40mm棒料，工件坐标系原点定在右端面中心O点。","options":[],"img":"https://cdn.jsdu.cn/opdav/20260606/cc4ba87bd00802a0bac22b9b8b6b539e.png","answer":"O0154;\\nG99 G21 G40 G80;\\nG54 G00 X45 Z5 M03 S1200;\\nT0101 M08;\\nG71 U1.5 R0.5;\\nG71 P10 Q20 U0.4 W0.1 F0.25;\\nN10 G00 X0;\\nG01 Z0 F0.12;\\nG03 X34 Z-17 R17; (车削前端球体SR17轮廓)\\nG01 Z-47; (精车切削φ34外圆段)\\nX36;\\nG02 X38 Z-48 R1; (车削顺时针R1倒圆角)\\nG01 Z-77; (精车切削φ38外圆)\\nX42; (径向退刀超出毛坯面)\\nN20 G00 Z5 M09;\\nG70 P10 Q20 F0.1; (调用G70精加工)\\nG00 X100 Z100 M05;\\nM30;","explanation":"工艺分析：前端为球头 $SR17$，对应的外径尺寸为 $\\\\phi 34$，圆弧段终点落在 $Z-17$ 处。中段由 $R1$ 的圆角顺时针过渡到 $\\\\phi 38$ 阶梯面，编程外廓需严格相切。","code":"O0154;\\nG99 G21 G40 G80;\\nG54 G00 X45 Z5 M03 S1200;\\nT0101 M08;\\nG71 U1.5 R0.5;\\nG71 P10 Q20 U0.4 W0.1 F0.25;\\nN10 G00 X0;\\nG01 Z0 F0.12;\\nG03 X34 Z-17 R17; (车削前端球体SR17轮廓)\\nG01 Z-47; (精车切削φ34外圆段)\\nX36;\\nG02 X38 Z-48 R1; (车削顺时针R1倒圆角)\\nG01 Z-77; (精车切削φ38外圆)\\nX42; (径向退刀超出毛坯面)\\nN20 G00 Z5 M09;\\nG70 P10 Q20 F0.1; (调用G70精加工)\\nG00 X100 Z100 M05;\\nM30;","codeLanguage":"c"},{"id":155,"type":"code","category":"程序设计","difficulty":3,"question":"2.根据图纸所示轴类台阶阶梯零件，请利用G71粗加工循环编写加工代码。工艺参数：刀具号T0101，起刀点(83,3)，转速1200r/min，每分钟进给F60，吃刀量2mm，径向精车余量0.1mm，轴向留0.2mm。","options":[],"img":"https://cdn.jsdu.cn/opdav/20260606/bce50862c13994ba7f73337fd3700bdf.png","answer":"O0155;\\nT0101;\\nG94 G00 X83 Z3 M03 S1200;\\nG71 U2.0 R0.5;\\nG71 P10 Q20 U0.1 W0.2 F60;\\nN10 G00 X20;\\nG01 Z0;\\nZ-20;\\nX35;\\nG02 X45 Z-25 R5; (加工R5顺圆台阶)\\nG01 Z-40;\\nX60;\\nZ-50;\\nX70 Z-55; (切削过渡斜角线段)\\nG03 X80 Z-65 R5; (车削左侧R5逆时针过渡弧)\\nG01 Z-80;\\nN20 X83;\\nG70 P10 Q20;\\nG00 X100 Z100 M05;\\nM30;","explanation":"补全核心：G94 强制激活每分钟毫米进给 F60。中间过度台阶包含 R5 的标准顺圆（G02）和后方 $5 \\\\times 5$ 的过渡倒斜角，以及尾部的 R5 逆圆（G03）。","code":"O0155;\\nT0101;\\nG94 G00 X83 Z3 M03 S1200;\\nG71 U2.0 R0.5;\\nG71 P10 Q20 U0.1 W0.2 F60;\\nN10 G00 X20;\\nG01 Z0;\\nZ-20;\\nX35;\\nG02 X45 Z-25 R5; (加工R5顺圆台阶)\\nG01 Z-40;\\nX60;\\nZ-50;\\nX70 Z-55; (切削过渡斜角线段)\\nG03 X80 Z-65 R5; (车削左侧R5逆时针过渡弧)\\nG01 Z-80;\\nN20 X83;\\nG70 P10 Q20;\\nG00 X100 Z100 M05;\\nM30;","codeLanguage":"c"},{"id":156,"type":"code","category":"程序设计","difficulty":4,"question":"3.如图所示多重曲率手柄轴类零件，请利用 G71 和 G70 指令将加工程序补全完整。起刀点选在(37,3)，进给速度每转进给0.45mm/r，吃刀量1.2mm，径向余量0.4mm，轴向余量0.1mm。","options":[],"img":"https://cdn.jsdu.cn/opdav/20260606/8eb40e1bbe30b751cf6d0d4afb8242db.png","answer":"O0156;\\nT0101 M03 S1200;\\nG99 G00 X37 Z3;\\nG71 U1.2 R0.5;\\nG71 P10 Q20 U0.4 W0.1 F0.45;\\nN10 G00 X0;\\nG01 Z0 F0.15;\\nG03 X7.28 Z-3.64 R3.64; (右端前侧半球小头圆弧)\\nG01 Z-10.28;\\nG02 X15.42 Z-23.02 R20.2; (切削中段下凹弧面R20.2)\\nG01 Z-27.16;\\nG02 X17.68 Z-34.92 R7.12; (切削鼓凸圆弧R7.12)\\nG01 Z-42.46;\\nG02 X23.08 Z-50.98 R8.52; (切削大球凸弧面)\\nN20 G00 X37;\\nG70 P10 Q20 F0.1;\\nG00 X100 Z100 M05;\\nM30;","explanation":"曲面难点：手柄是一段连续非单调切向弧线。最前部顶端小球属于逆圆 G03，随后的内凹过渡中腰身以及后方鼓凸均需顺车刀动线看作 G02 顺圆，坐标依赖图纸累加。","code":"O0156;\\nT0101 M03 S1200;\\nG99 G00 X37 Z3;\\nG71 U1.2 R0.5;\\nG71 P10 Q20 U0.4 W0.1 F0.45;\\nN10 G00 X0;\\nG01 Z0 F0.15;\\nG03 X7.28 Z-3.64 R3.64; (右端前侧半球小头圆弧)\\nG01 Z-10.28;\\nG02 X15.42 Z-23.02 R20.2; (切削中段下凹弧面R20.2)\\nG01 Z-27.16;\\nG02 X17.68 Z-34.92 R7.12; (切削鼓凸圆弧R7.12)\\nG01 Z-42.46;\\nG02 X23.08 Z-50.98 R8.52; (切削大球凸弧面)\\nN20 G00 X37;\\nG70 P10 Q20 F0.1;\\nG00 X100 Z100 M05;\\nM30;","codeLanguage":"c"},{"id":157,"type":"code","category":"程序设计","difficulty":3,"question":"4. 如图所示板类模板零件，本工序用φ8mm立铣刀顺向精铣铣削外轮廓。起刀点设置在原点(0,0,50)，加工深度2mm。转速2000r/min，进给F150，程序中要求包含半径补偿偏置指令。","options":[],"img":"https://cdn.jsdu.cn/opdav/20260606/2e01bbb63b61018c94f8ebed21f1983d.png","answer":"O0157;\\nG90 G54 G00 X0 Y0 Z50 M03 S2000;\\nG01 Z-2 F150 M08;\\nG41 G01 X20 Y10 D01; (顺轨迹左偏置切入起点)\\nX60;\\nY40;\\nX70;\\nY50;\\nG02 X60 Y60 R10; (顺铣右上外圆角)\\nG01 X50;\\nG02 X30 Y60 R10; (顺切中部内凹180度桥弧)\\nG01 X20;\\nG03 X10 Y50 R10; (逆铣左上角过渡孤轮廓)\\nG01 Y40;\\nX20;\\nY10;\\nG40 G00 X0 Y0 Z50 M09;\\nM05;\\nM30;","explanation":"网格制图：按 10x10 的网格交点精确读取绝对坐标。顺箭头切削时，刀具中心始终偏在零件工件的左侧，故用 G41 D01 建立左刀补，最后回到安全区用 G40 清除偏置。","code":"O0157;\\nG90 G54 G00 X0 Y0 Z50 M03 S2000;\\nG01 Z-2 F150 M08;\\nG41 G01 X20 Y10 D01; (顺轨迹左偏置切入起点)\\nX60;\\nY40;\\nX70;\\nY50;\\nG02 X60 Y60 R10; (顺铣右上外圆角)\\nG01 X50;\\nG02 X30 Y60 R10; (顺切中部内凹180度桥弧)\\nG01 X20;\\nG03 X10 Y50 R10; (逆铣左上角过渡孤轮廓)\\nG01 Y40;\\nX20;\\nY10;\\nG40 G00 X0 Y0 Z50 M09;\\nM05;\\nM30;","codeLanguage":"c"},{"id":158,"type":"code","category":"程序设计","difficulty":3,"question":"5.请根据零件图纸，利用数控铣床编写图示凸台零件外轮廓的核心走刀加工轨迹。凸台整体边界尺寸80x60，对称中心轴位于原点，包含R10、R20圆角与两个切斜角段。","options":[],"img":"","answer":"O0158;\\n... \\nG01 Z-5 F150;\\nG41 G01 X-40 Y-15 D01; (切向建立左偏置切入左壁)\\nG01 Y15;\\nX-26 Y30; (切斜角14mm段)\\nG01 X20;\\nG02 X40 Y10 R20; (顺铣右上大圆弧角R20)\\nG01 Y-15;\\nX25 Y-30; (铣削右下角对称倒斜角面)\\nG01 X-30;\\nG03 X-40 Y-20 R10; (逆铣左下拐角内凹过渡圆角R10)\\nG01 Y-15;\\nG40 G00 X0 Y0 Z50;\\n...","explanation":"读图技巧：凸台对称定于原点。左上斜切线段对应 $X-40$ 行至 $X-26$。右上拐角为 R20 顺弧插补（G02），左下闭合拐角为 R10 的逆圆铣削（G03）。"},{"id":159,"type":"code","category":"程序设计","difficulty":3,"question":"6.根据图纸，编写零件图号为X30-01的锻铝凸模主体外轮廓精铣轨迹。凸台外缘由多段大半径R圆弧过渡构成，只需编写零件核心轮廓的加工路径。","options":[],"img":"","answer":"O0159;\\n... \\nG01 Z-5 F150;\\nG41 G01 X-10 Y-30 D01; (切向进入工件下侧直壁面)\\nX18;\\nG02 X28 Y-20 R10; (顺圆过渡右底圆弧角R10)\\nG01 Y0;\\nG02 X10 Y30 R18; (顺铣右上相切复合大R圆弧外廓)\\nG01 X-10;\\nG02 X-38 Y0 R28; (顺切左侧相切大半径凸轮包络弧段)\\nG02 X-10 Y-30 R28; (圆滑铣下底部圆弧段闭合循环)\\nG40 G00 X-60 Y-50 Z50;\\nM30;","explanation":"几何相切：本凸模难点是由 R18、R28 等大半径曲线在两侧切向无缝融合而成。必须精准对齐图纸标定的圆心相对偏置距离，确保顺铣 G02 插补无凹坑阶梯。"}]' WHERE id = 'cnc-machining-full-2026';